INSERT INTO `end_of_contract` (`eoc_id`, `content`, `display_order`) VALUES
(1, 'ผลงานตีพิมพ์ที่ขอรับการสนับสนุนไม่เคยได้รับการจัดสรรทุนของมหาวิทยาลัย และทุนส่งเสริมการวิจัยจากกองทุนวิจัย นวัตกรรม และบริการวิชาการ วิทยาลัยการคอมพิวเตอร์', 1),
(2, 'จะปฏิบัติตามระเบียบมหาวิทยาลัยขอนแก่น ว่าด้วยกองทุนวิจัยในระดับคณะ พ.ศ. 2568 รวมถึงหลักเกณฑ์และประกาศอื่นใดที่เกี่ยวข้องทุกประการ', 2),
(3, 'ผลงานตีพิมพ์ที่ขอรับการสนับสนุนไม่เคยได้รับทุนส่งเสริมการวิจัยจากกองทุนวิจัย นวัตกรรม และบริการวิชาการวิทยาลัยการคอมพิวเตอร์ ไม่เคยได้รับการจัดสรรทุนของมหาวิทยาลัย', 3);
